package tools

import (
	"encoding/json"
	"fmt"
	"runtime"
	"strings"
	"testing"
)

// scrubber replaces the temporary folders in a result with the names the golden file uses.
func scrubber(base, root string) func(string) string {
	return func(s string) string {
		return strings.ReplaceAll(strings.ReplaceAll(s, root, "<ROOT>"), base, "<BASE>")
	}
}

// supersededByContainment are the golden calls whose Elixir result came from reading outside
// the repository root or through the home folder; the reading tools now refuse them (see
// TestReadContainFaults), so only the refusal is asserted for them.
var supersededByContainment = map[string]bool{
	`read_file {"path":"//a.txt"}`:                               true,
	`read_file {"path":"../kogen-agent-definitely-missing-xyz"}`: true,
	`read_file {"path":"~/kogen-agent-missing-xyz"}`:             true,
	`read_file {"path":"~"}`:                                     true,
	`read_file {"path":"\/a.txt"}`:                               true,
	`list_files {"path":"../x"}`:                                 true,
	`list_files {"path":"/tmp"}`:                                 true,
	`view_image {"path":"~/kogen-missing.png"}`:                  true,
	`search_text {"pattern":"needle","path":"../x"}`:             true,
}

// TestToolsMatchTheElixirResults replays every call of the golden file (generated by
// testdata/gen_tools.exs from the Elixir Kogen.Tools) in the same repository and compares
// the results: read_file, write_file (protected path), list_files, search_text, unknown
// tools, argument decoding and view_image, which covers the PNG limits and messages.
func TestToolsMatchTheElixirResults(t *testing.T) {
	g := loadGolden(t)
	base, root := g.build(t)
	scrub := scrubber(base, root)
	tools := newTools(root, g.Tools...)
	tools.Protected = g.Protected

	for i, c := range g.Calls {
		name := fmt.Sprintf("%03d %s %s", i, c.Name, c.Arguments)
		if len(name) > 100 {
			name = name[:100]
		}
		t.Run(name, func(t *testing.T) {
			args := DecodeArguments(strings.ReplaceAll(c.Arguments, "<ROOT>", root))
			out, err := tools.Run(c.Name, args)
			if err != nil {
				t.Fatal(err)
			}
			var wantText string
			if json.Unmarshal(c.Result, &wantText) == nil {
				if out.Typed() {
					t.Fatalf("typed result, want text %q", wantText)
				}
				got := scrub(out.Text)
				if supersededByContainment[c.Name+" "+c.Arguments] {
					if !strings.HasPrefix(got, "error: ") || !strings.Contains(got, "confined to the repository root") {
						t.Errorf("not refused by containment: %q", got)
					}
					return
				}
				if runtime.GOOS != "darwin" && strings.HasPrefix(wantText, "error: fatal: -e option, ") {
					// Git quotes the C library's regular expression error, which differs.
					wantText, got = "error: fatal: ", got[:min(len(got), len("error: fatal: "))]
				}
				if runtime.GOOS != "darwin" && c.Name == "search_text" && c.Arguments == `{"pattern":"\\bfunc\\b"}` {
					// The C library's regular expressions treat \b as a word boundary on Linux only.
					wantText = "src/main.go:3:func main() {}"
				}
				if got != wantText {
					t.Errorf("result\n got: %q\nwant: %q", got, wantText)
				}
				return
			}
			var want []map[string]string
			if err := json.Unmarshal(c.Result, &want); err != nil {
				t.Fatal(err)
			}
			if !out.Typed() {
				t.Fatalf("text result %q, want typed parts", out.Text)
			}
			if len(out.Parts) != len(want) {
				t.Fatalf("%d parts, want %d", len(out.Parts), len(want))
			}
			for j, p := range out.Parts {
				part := p.(map[string]any)
				for k, wantValue := range want[j] {
					got, _ := part[k].(string)
					if got = scrub(got); got != wantValue {
						t.Errorf("part %d %s\n got: %q\nwant: %q", j, k, got, wantValue)
					}
				}
				if len(part) != len(want[j]) {
					t.Errorf("part %d has keys %v, want %d", j, part, len(want[j]))
				}
			}
		})
	}
}
